var n=`0031-pierogi-ruskie`;var t=`world-0031`;var o=`PL`;var a=`eastern-europe`;var l=4;var s=83;var g={en:`Pierogi Ruskie`,ua:`Пироги руські`};var r={en:`A classic dish from Poland, featuring chicken egg, potato, quark, yellow onion. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Польща. Основні складники: куряче яйце, картопля, кварк, жовта цибуля. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var u=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 25 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 25 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:25,i:[[`all-purpose-flour`,490,`g`],[`water`,230,`ml`],[`chicken-egg`,1,`pcs`],[`table-salt`,4,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:25,i:[[`potato`,550,`g`],[`quark`,280,`g`],[`yellow-onion`,150,`g`],[`unsalted-butter`,40,`g`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Roll the rested dough thinly, cut rounds, place filling in the center and pinch each dumpling tightly closed.`,ua:`Тонко розкачайте відпочиле тісто, виріжте кружальця, викладіть начинку в центр і ретельно заліпіть краї кожного вареника чи пельменя.`,t:[`rolling-out-dough`,`pinching-dumplings`],m:25,i:[]},{en:`Cook dumplings in batches in gently boiling salted water for about 6 minutes, until they float and the filling is cooked through. Lift out with a slotted spoon.`,ua:`Варіть вироби порціями в ледь киплячій підсоленій воді приблизно 6 хвилин, доки вони спливуть і начинка приготується. Вийміть шумівкою.`,t:[`boiling`],m:6,i:[[`water`,1400,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`sour-cream`,110,`g`]]}];var h={slug:n,id:t,country:`PL`,region:a,servings:4,minutes:83,title:g,text:r,steps:u};export{o as country,h as default,t as id,s as minutes,a as region,l as servings,n as slug,u as steps,r as text,g as title};